package web

const baseCSS = `:root{--bg:#f4f7fb;--ink:#172033;--muted:#64748b;--panel:#fff;--line:#d8e1ee;--blue:#2563eb;--cyan:#0891b2;--green:#059669;--red:#dc2626;--shadow:0 18px 45px rgba(15,23,42,.10)}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(135deg,#f7fbff,#edf7f9 54%,#f7f8fb);color:var(--ink);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{width:min(1180px,calc(100% - 28px));margin:0 auto;padding:28px 0}.brand{display:flex;gap:13px;align-items:center}.mark{width:46px;height:46px;border-radius:8px;background:linear-gradient(135deg,var(--blue),var(--cyan));display:grid;place-items:center;color:#fff;font-weight:850}h1{font-size:24px;margin:0}.sub{color:var(--muted)}button,a.btn{border:1px solid var(--line);border-radius:8px;padding:10px 14px;background:#fff;color:var(--ink);font-weight:750;text-decoration:none;cursor:pointer}button.primary{background:var(--blue);border-color:var(--blue);color:#fff}.panel,.hero{background:var(--panel);border:1px solid var(--line);border-radius:8px;box-shadow:var(--shadow)}input{border:1px solid var(--line);border-radius:8px;padding:11px 12px;font:inherit;width:100%}.form{display:grid;gap:12px}.err{color:var(--red);min-height:20px}.top,.head,.tools{display:flex;justify-content:space-between;gap:14px;align-items:center}.tools{justify-content:flex-start;flex-wrap:wrap}.domain{font-size:clamp(28px,5vw,52px);font-weight:900;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:1fr 380px;gap:18px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.card{border:1px solid var(--line);border-radius:8px;padding:14px;background:#fbfdff}.k{color:var(--muted);font-size:13px}.v{font-size:22px;font-weight:850}.bar{height:10px;border-radius:999px;background:#e5edf7;overflow:hidden;margin-top:8px}.fill{height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--cyan));transition:width .25s}.panel .head{padding:16px 18px;border-bottom:1px solid var(--line)}.body{padding:16px 18px}.kv{display:grid;gap:10px}.row{display:flex;justify-content:space-between;gap:12px;border-bottom:1px dashed var(--line);padding-bottom:10px}.row:last-child{border:0;padding-bottom:0}.row span:last-child{text-align:right;font-weight:750;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 14px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-size:12px;background:#fbfdff}.ip{font-family:Consolas,monospace;font-weight:800}.speed{color:var(--green);font-weight:850}.empty{padding:24px;color:var(--muted)}.modal{position:fixed;inset:0;background:rgba(15,23,42,.48);display:grid;place-items:center;padding:18px}.modal[hidden]{display:none}.box{width:min(560px,100%);background:#fff;border-radius:8px;border:1px solid var(--line);box-shadow:var(--shadow);padding:22px}@media(max-width:900px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.top{display:grid}table{display:block;overflow-x:auto}}@media(max-width:520px){.stats{grid-template-columns:1fr}.head{display:grid}}`

const setupHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Title}} Setup</title><style>` + baseCSS + `.setup{width:min(560px,calc(100% - 28px));margin:8vh auto}.setup .panel{padding:26px}.setup h1{font-size:30px}.lead{margin:10px 0 22px;color:var(--muted)}</style></head><body><main class="setup"><section class="panel"><div class="brand"><div class="mark">CF</div><div><h1>{{.Title}}</h1><div class="sub">&#39318;&#27425;&#21021;&#22987;&#21270;</div></div></div><p class="lead">&#35831;&#20808;&#35774;&#32622;&#31649;&#29702;&#21592;&#36134;&#21495;&#21644;&#23494;&#30721;&#12290;&#23436;&#25104;&#21518;&#20250;&#33258;&#21160;&#36827;&#20837; /admin &#31649;&#29702;&#38754;&#26495;&#65292;&#22495;&#21517;&#32465;&#23450;&#22312;&#38754;&#26495;&#20013;&#24341;&#23548;&#23436;&#25104;&#12290;</p><div class="form"><input id="user" value="admin" autocomplete="username"><input id="pass" type="password" placeholder="至少 8 位密码" autocomplete="new-password"><div class="err" id="err"></div><button class="primary" id="setupBtn">&#23436;&#25104;&#21021;&#22987;&#21270;</button></div></section></main><script>setupBtn.onclick=async()=>{err.textContent='';setupBtn.disabled=true;try{const r=await fetch('/api/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({admin_user:user.value,password:pass.value,panel_url:location.host,domain:''})});if(!r.ok)throw new Error(await r.text());location.href='/admin'}catch(e){err.textContent=e.message;setupBtn.disabled=false}}</script></body></html>`

const publicHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Title}}</title><style>` + baseCSS + `.hero{padding:28px;margin-top:22px}.badge{display:inline-flex;gap:8px;align-items:center;border:1px solid var(--line);border-radius:999px;padding:6px 10px;background:#f8fafc;color:var(--muted);font-weight:700}.dot{width:8px;height:8px;border-radius:99px;background:var(--green)}.dot.running{background:var(--cyan)}.dot.error{background:var(--red)}</style></head><body><main class="wrap"><div class="top"><div class="brand"><div class="mark">CF</div><div><h1>{{.Title}}</h1><div class="sub">&#20844;&#24320;&#36816;&#34892;&#29366;&#24577;</div></div></div><a class="btn" href="/admin">Admin</a></div><section class="hero"><div class="badge"><span id="dot" class="dot"></span><span id="state">&#21152;&#36733;&#20013;</span></div><div class="domain" id="domain">{{.Domain}}</div><div class="sub">&#27492;&#39029;&#21482;&#23637;&#31034;&#31995;&#32479;&#29366;&#24577;&#65292;&#19981;&#20844;&#24320;&#20248;&#36873; IP&#12290;</div><div class="stats"><div class="card"><div class="k">&#24050;&#36816;&#34892;</div><div class="v" id="uptime">-</div></div><div class="card"><div class="k">&#24050;&#27979;&#24402;&#26723; IP</div><div class="v" id="tested">0</div></div><div class="card"><div class="k">&#24403;&#21069;&#21457;&#24067;&#25968;</div><div class="v" id="published">0</div></div><div class="card"><div class="k">&#26368;&#36817;&#36816;&#34892;</div><div class="v" id="last">-</div></div></div><div class="sub" id="stage" style="margin-top:18px"></div></section></main><script>const startedAt=Date.now(),fmt=new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'medium'});function dur(s){if(s<60)return s+' \u79d2';let m=Math.floor(s/60);if(m<60)return m+' \u5206\u949f';let h=Math.floor(m/60);if(h<24)return h+' \u5c0f\u65f6';return Math.floor(h/24)+' \u5929'}async function refresh(){const r=await fetch('/api/public',{cache:'no-store'}),d=await r.json(),s=d.status||{};domain.textContent=(d.config&&d.config.domain)||'\u672a\u8bbe\u7f6e';uptime.textContent=dur(Math.floor((Date.now()-startedAt)/1000));tested.textContent=(d.archive&&d.archive.tested_ips)||0;published.textContent=s.published_ips||0;last.textContent=s.last_ended?fmt.format(new Date(s.last_ended)):'-';stage.textContent=cnStage(s.stage);dot.className='dot';if(s.running){dot.classList.add('running');state.textContent='\u6b63\u5728\u6d4b\u901f'}else if(s.last_error){dot.classList.add('error');state.textContent='\u8fd0\u884c\u5f02\u5e38'}else state.textContent='\u8fd0\u884c\u6b63\u5e38'}function cnStage(v){if(!v)return'\u7a7a\u95f2';return v.replace('Finished','\u8fd0\u884c\u5b8c\u6210').replace('Preparing','\u51c6\u5907\u6d4b\u901f').replace(/Delay test (\d+)\/(\d+), available (\d+)/,'\u5ef6\u8fdf\u6d4b\u901f $1/$2\uff0c\u53ef\u7528 $3').replace(/Download test (\d+)\/(\d+)/,'\u4e0b\u8f7d\u6d4b\u901f $1/$2')}refresh();setInterval(refresh,5000)</script></body></html>`

const adminHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Title}} Admin</title><style>` + baseCSS + `.hero{padding:24px;margin:22px 0}.mini{font-family:Consolas,monospace;color:var(--muted)}</style></head><body><main class="wrap"><div class="top"><div class="brand"><div class="mark">CF</div><div><h1>{{.Title}}</h1><div class="sub">&#31649;&#29702;&#38754;&#26495;</div></div></div><div class="tools"><a class="btn" href="/">Status</a><button id="domainBtn">&#32465;&#23450;&#22495;&#21517;</button><button id="accountBtn">&#36134;&#25143;</button><button id="logoutBtn">&#36864;&#20986;</button><button class="primary" id="runBtn">&#31435;&#21363;&#27979;&#36895;</button></div></div><section class="hero"><div class="head"><div><div class="sub">&#20248;&#36873;&#22495;&#21517;</div><div class="domain" id="domain">{{.Domain}}</div></div><span id="state">&#21152;&#36733;&#20013;</span></div><div class="stats"><div class="card"><div class="k">&#36718;&#27425;</div><div class="v" id="round">-</div></div><div class="card"><div class="k">&#24050;&#36873;</div><div class="v" id="selected">-</div></div><div class="card"><div class="k">&#20505;&#36873;</div><div class="v" id="candidates">0</div></div><div class="card"><div class="k">&#32791;&#26102;</div><div class="v" id="elapsed">-</div></div></div><div style="margin-top:16px"><div class="sub" id="delayText">&#24310;&#36831;&#27979;&#36895; 0/0</div><div class="bar"><div class="fill" id="delayFill"></div></div></div><div style="margin-top:12px"><div class="sub" id="downText">&#19979;&#36733;&#27979;&#36895; 0/0</div><div class="bar"><div class="fill" id="downFill"></div></div></div><div class="sub" id="stage" style="margin-top:14px"></div><div class="mini" id="live"></div></section><div class="grid"><section class="panel"><div class="head"><h2>&#24403;&#21069;&#20248;&#36873; IP</h2><span id="generated" class="sub"></span></div><div id="table" class="empty">&#26242;&#26080;&#21457;&#24067;&#32467;&#26524;</div></section><aside class="panel"><div class="head"><h2>&#36816;&#34892;&#20449;&#24687;</h2></div><div class="body kv" id="info"></div></aside></div></main><div class="modal" id="login" hidden><div class="box"><h2>&#31649;&#29702;&#21592;&#30331;&#24405;</h2><div class="form"><input id="lu" value="admin" autocomplete="username"><input id="lp" type="password" autocomplete="current-password"><div class="err" id="le"></div><button class="primary" id="loginBtn">&#30331;&#24405;</button></div></div></div><div class="modal" id="domainModal" hidden><div class="box"><h2>&#32465;&#23450;&#20248;&#36873;&#22495;&#21517;</h2><p class="sub" id="domainGuide"></p><div class="form"><input id="domainInput" placeholder="cfip.example.com"><div class="err" id="de"></div><button class="primary" id="saveDomain">&#20445;&#23384;&#22495;&#21517;</button><button id="closeDomain">&#21462;&#28040;</button></div></div></div><div class="modal" id="accountModal" hidden><div class="box"><h2>&#31649;&#29702;&#21592;&#36134;&#25143;</h2><div class="form"><input id="au" autocomplete="username"><input id="cp" type="password" placeholder="当前密码"><input id="np" type="password" placeholder="新密码，可留空"><div class="err" id="ae"></div><button class="primary" id="saveAccount">&#20445;&#23384;&#36134;&#25143;</button><button id="closeAccount">&#21462;&#28040;</button></div></div></div><script>const fmt=new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'medium'});let last={};async function api(url,opt){const r=await fetch(url,opt);if(r.status===401){login.hidden=false;throw new Error('login required')}if(r.status===403){location.href='/';throw new Error('setup required')}if(!r.ok)throw new Error(await r.text());return r.json()}loginBtn.onclick=async()=>{le.textContent='';try{await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({admin_user:lu.value,password:lp.value})});login.hidden=true;refresh()}catch(e){le.textContent=e.message}};logoutBtn.onclick=async()=>{await fetch('/api/logout',{method:'POST'});location.href='/admin'};runBtn.onclick=async()=>{await api('/api/run',{method:'POST'});refresh()};domainBtn.onclick=()=>{domainGuide.textContent='\u5f53\u524d\u9762\u677f\u5730\u5740\uff1a'+location.host+'\u3002\u5982\u679c\u4f60\u6709\u516c\u7f51 IP\uff0c\u8bf7\u5728 DNS \u91cc\u628a\u4f60\u7684\u57df\u540d A \u8bb0\u5f55\u6307\u5411 NAS \u516c\u7f51 IP\uff1b\u82e5\u6ca1\u6709\u516c\u7f51 IP\uff0c\u53ef\u5148\u53ea\u5728\u5c40\u57df\u7f51\u4f7f\u7528\u9762\u677f\u3002';domainInput.value=last.config?last.config.domain:'';domainModal.hidden=false};closeDomain.onclick=()=>domainModal.hidden=true;saveDomain.onclick=async()=>{de.textContent='';try{const d=await api('/api/config/domain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain:domainInput.value})});domain.textContent=d.domain;domainModal.hidden=true;refresh()}catch(e){de.textContent=e.message}};accountBtn.onclick=()=>{au.value=(last.setup&&last.setup.admin_user)||'admin';accountModal.hidden=false};closeAccount.onclick=()=>accountModal.hidden=true;saveAccount.onclick=async()=>{ae.textContent='';try{await api('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({admin_user:au.value,current_password:cp.value,new_password:np.value})});accountModal.hidden=true;cp.value='';np.value='';refresh()}catch(e){ae.textContent=e.message}};async function refresh(){let d;try{d=await api('/api/status',{cache:'no-store'});last=d}catch(e){return}const s=d.status,c=d.config,p=s.progress||{},ips=(s.published&&s.published.ips)||[];domain.textContent=c.domain;state.textContent=s.running?'\u6b63\u5728\u6d4b\u901f':(s.last_error?'\u8fd0\u884c\u5f02\u5e38':'\u8fd0\u884c\u6b63\u5e38');round.textContent=s.current_round?(s.current_round+' / '+s.rounds):'-';selected.textContent=(s.selected||0)+' / '+(s.target||c.desired_unique_ips);candidates.textContent=s.candidates||0;elapsed.textContent=s.elapsed_sec?(s.elapsed_sec+' \u79d2'):'-';stage.textContent=cnStage(s.stage);delayText.textContent='\u5ef6\u8fdf\u6d4b\u901f '+(p.delay_done||0)+'/'+(p.delay_total||0)+'\uff0c\u53ef\u7528 '+(p.available||0);downText.textContent='\u4e0b\u8f7d\u6d4b\u901f '+(p.download_done||0)+'/'+(p.download_total||0)+'\uff0c\u6709\u6548 '+(p.usable_results||0);delayFill.style.width=percent(p.delay_done,p.delay_total);downFill.style.width=percent(p.download_done,p.download_total);live.textContent=(p.current_ip?('\u5f53\u524d IP '+p.current_ip+'  '):'')+(p.last_ip?('\u4e0a\u4e00\u4e2a '+p.last_ip+' '+Number(p.last_speed_mbps||0).toFixed(2)+' MB/s'):'');generated.textContent=s.published&&s.published.generated_at?('\u53d1\u5e03\u4e8e '+fmt.format(new Date(s.published.generated_at))):'\u7b49\u5f85\u53d1\u5e03';renderTable(ips);info.innerHTML=rows([['\u7ba1\u7406\u5458',d.setup.admin_user],['\u5f52\u6863\u8f6e\u6b21',d.archive.cycles],['\u5df2\u6d4b\u5f52\u6863 IP',d.archive.tested_ips],['\u8ba1\u5212\u4efb\u52a1',c.schedule],['\u6bcf\u5c0f\u65f6\u8f6e\u6b21',c.rounds_per_hour],['\u4e0b\u8f7d\u5730\u5740',c.download_url],['\u76d1\u542c\u5730\u5740',c.web_listen]])}function renderTable(ips){if(!ips.length){table.className='empty';table.textContent='\u6682\u65e0\u53d1\u5e03\u7ed3\u679c\uff0c\u6216\u672c\u8f6e\u672a\u6d4b\u5230\u6709\u6548\u4e0b\u8f7d\u901f\u5ea6';return}table.className='';table.innerHTML='<table><thead><tr><th>#</th><th>IP</th><th>\u901f\u5ea6</th><th>\u5ef6\u8fdf</th><th>\u4e22\u5305</th><th>\u8282\u70b9</th><th>\u8f6e\u6b21</th></tr></thead><tbody>'+ips.map((x,i)=>'<tr><td>'+(i+1)+'</td><td class="ip">'+esc(x.ip)+'</td><td class="speed">'+Number(x.download_mbps).toFixed(2)+' MB/s</td><td>'+Number(x.delay_ms).toFixed(2)+' ms</td><td>'+(Number(x.loss_rate)*100).toFixed(0)+'%</td><td>'+esc(x.colo||'N/A')+'</td><td>'+x.round+'</td></tr>').join('')+'</tbody></table>'}function rows(a){return a.map(x=>'<div class="row"><span>'+x[0]+'</span><span>'+esc(String(x[1]??''))+'</span></div>').join('')}function percent(a,b){return b?Math.min(100,Math.round(a/b*100))+'%':'0%'}function esc(v){return v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function cnStage(v){if(!v)return'\u7a7a\u95f2';return v.replace('Finished','\u8fd0\u884c\u5b8c\u6210').replace('Preparing','\u51c6\u5907\u6d4b\u901f').replace(/Delay test (\d+)\/(\d+), available (\d+)/,'\u5ef6\u8fdf\u6d4b\u901f $1/$2\uff0c\u53ef\u7528 $3').replace(/Download test (\d+)\/(\d+)/,'\u4e0b\u8f7d\u6d4b\u901f $1/$2').replace(/Selected (\d+)\/(\d+) IPs/,'\u5df2\u9009\u51fa $1/$2 \u4e2a IP').replace(/Round (\d+) produced no positive-speed result/,'\u7b2c $1 \u8f6e\u672a\u6d4b\u5230\u6709\u6548\u901f\u5ea6')}refresh();setInterval(refresh,3000)</script></body></html>`
